class Rectangle {
    constructor(clr) {
        this.x = random(-windowWidth / 2, windowWidth / 2);
        this.y = random(-windowHeight / 2, windowHeight / 2);
        this.size = 0;
        this.maxSize = 200; // random(50, 200);
        this.growing = true;
        this.color = clr; // color(random(255), random(255), random(255)); // color(random(200, 255), random(100), random(100, 200));
        this.angle = random(TWO_PI);
    }

    update() {
        if (this.growing) {
            this.size = min(this.size + 3, this.maxSize);
            this.growing = this.size < this.maxSize;
        } else {
            this.size = max(this.size - 3, 0);
            if (this.size === 0) return true;
        }

        if (!this.growing && random() < 0.01) this.growing = true;
        if (random() < 0.01) this.growing = false;

				this.size = this.maxSize * 3;
				this.angle += this.y/height/30;

        return false;
    }

    display() {
      push();
        // translate(this.x, this.y); // translate(this.x, this.y);
				rotateX(-0.5); // (-((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height)+0.5);
        rotateY(this.angle); // rotateY(1);
