	lights();
	directionalLight(255, 255, 255, 0, 0, -1);

	if (true)
	rectangles = rectangles.filter((rect) => {
			rect.update();
			rect.display();
			return rect.size > 0;
	});

	if (false) {
		stroke(255)
		strokeWeight(2)
		fill(0)
		push()
		const ang = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -TAU, TAU)
		rotateY(ang)
